import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    filenames = []
    for _ in range(n):
        filenames.append(next(iterator))

    indices_to_delete = []
    for _ in range(m):
        indices_to_delete.append(int(next(iterator)))

    files_to_delete = [filenames[i - 1] for i in indices_to_delete]
    files_not_to_delete = []
    for i in range(1, n + 1):
        if i not in indices_to_delete:
            files_not_to_delete.append(filenames[i - 1])

    if m > 0:
        target_len = len(files_to_delete[0])
        for f in files_to_delete:
            if len(f) != target_len:
                print("No")
                return

        pattern_chars = []
        for pos in range(target_len):
            chars_at_pos = set(f[pos] for f in files_to_delete)
            if len(chars_at_pos) == 1:
                pattern_chars.append(list(chars_at_pos)[0])
            else:
                pattern_chars.append('?')

        pattern = "".join(pattern_chars)

        def matches(pattern, s):
            if len(pattern) != len(s):
                return False
            for p_char, s_char in zip(pattern, s):
                if p_char != '?' and p_char != s_char:
                    return False
            return True

        for f in files_to_delete:
            if not matches(pattern, f):
                print("No")
                return

        for f in files_not_to_delete:
            if matches(pattern, f):
                print("No")
                return

    else:
        pattern = ""
        if files_not_to_delete:
            print("No")
            return
        print("Yes")
        print("")
        return

    print("Yes")
    print(pattern)

if __name__ == "__main__":
    main()
